  {code:'+971',name:'UAE +971'},{code:'+91',name:'India +91'},{code:'+1',name:'USA +1'},
  {code:'+44',name:'UK +44'},{code:'+92',name:'Pakistan +92'},{code:'+880',name:'Bangladesh +880'},
  {code:'+63',name:'Philippines +63'},{code:'+20',name:'Egypt +20'},{code:'+966',name:'Saudi Arabia +966'},
