  {code:'+60',name:'Malaysia +60'},{code:'+65',name:'Singapore +65'},{code:'+66',name:'Thailand +66'},
  {code:'+84',name:'Vietnam +84'},{code:'+62',name:'Indonesia +62'},{code:'+94',name:'Sri Lanka +94'},
  {code:'+977',name:'Nepal +977'},{code:'+974',name:'Qatar +974'},{code:'+965',name:'Kuwait +965'},
  {code:'+973',name:'Bahrain +973'},{code:'+968',name:'Oman +968'},{code:'+967',name:'Yemen +967'},
  {code:'+213',name:'Algeria +213'},{code:'+212',name:'Morocco +212'},{code:'+216',name:'Tunisia +216'},
  {code:'+249',name:'Sudan +249'},{code:'+251',name:'Ethiopia +251'},{code:'+233',name:'Ghana +233'},
  {code:'+255',name:'Tanzania +255'},{code:'+256',name:'Uganda +256'},{code:'+263',name:'Zimbabwe +263'}
];
var COUNTRIES = ['Afghanistan','Albania','Algeria','Andorra','Angola','Argentina','Armenia','Australia',
  'Austria','Azerbaijan','Bahrain','Bangladesh','Belarus','Belgium','Bhutan','Bolivia','Bosnia','Brazil',
  'Bulgaria','Cambodia','Canada','Chile','China','Colombia','Croatia','Cuba','Cyprus','Czech Republic',
  'Denmark','Egypt','Estonia','Ethiopia','Finland','France','Germany','Ghana','Greece','Hungary',
  'India','Indonesia','Iran','Iraq','Ireland','Israel','Italy','Japan','Jordan','Kazakhstan','Kenya',
  'Kuwait','Kyrgyzstan','Latvia','Lebanon','Libya','Lithuania','Luxembourg','Malaysia','Maldives',
  'Malta','Mexico','Moldova','Mongolia','Morocco','Mozambique','Myanmar','Nepal','Netherlands',
  'New Zealand','Nigeria','North Korea','Norway','Oman','Pakistan','Palestine','Panama','Peru',
  'Philippines','Poland','Portugal','Qatar','Romania','Russia','Saudi Arabia','Serbia','Singapore',
  'Slovakia','Slovenia','South Africa','South Korea','Spain','Sri Lanka','Sudan','Sweden',
  'Switzerland','Syria','Taiwan','Tajikistan','Tanzania','Thailand','Tunisia','Turkey','Turkmenistan',
  'Uganda','Ukraine','United Arab Emirates','United Kingdom','United States','Uruguay','Uzbekistan',
  'Venezuela','Vietnam','Yemen','Zimbabwe'];

function populateCountryCodes(selId) {
  var sel = document.getElementById(selId); if(!sel) return;
  COUNTRY_CODES.forEach(function(c){
    var opt=document.createElement('option'); opt.value=c.code; opt.textContent=c.name;
    sel.appendChild(opt);
  });
  var saved = sel.getAttribute('data-selected');
  if(saved) sel.value = saved; else sel.value = '+971';
}
function populateCountries() {
  var sel = document.getElementById('licenseCountrySel'); if(!sel) return;
  var ph=document.createElement('option'); ph.value=''; ph.textContent='Driving license country of issue'; sel.appendChild(ph);
  COUNTRIES.forEach(function(c){ var opt=document.createElement('option'); opt.value=c; opt.textContent=c; sel.appendChild(opt); });
  var saved = sel.getAttribute('data-selected');
  if(saved) sel.value = saved;
}
function toggleTransferYesNo(val) {
  document.getElementById('transfer_not_possible').classList.toggle('hidden', val!=='no');
  document.getElementById('sec_transfer_applicant').classList.toggle('hidden', val!=='yes');
  document.getElementById('sec_transfer_no_applicant').classList.toggle('hidden', val!=='no');
}
function setLbl(input, labelId) {
  if(input.files&&input.files[0]) document.getElementById(labelId).textContent=input.files[0].name;
}

var parts = window.location.pathname.split('/');
var dlType = parts[parts.length-2];
var steps = STEP_LABELS[dlType]||STEP_LABELS['new'];
var fee = FEE_MAP[dlType]||'-';
document.getElementById('feeVal').textContent = fee;
var titleMap = {new:'New',amendment:'Amendment',duplicate:'Duplicate',renewal:'Renewal',transfer:'Transfer'};
document.getElementById('formTitle').textContent = titleMap[dlType]||'New';
document.getElementById('mainForm').action = '/spc/concierge/driving-license/'+dlType+'/step1/submit';

var html='';
steps.forEach(function(s,i){
  var cls = i===0?' active':'';
  html+='

'+(i+1)+'
'+s+'';
});
document.getElementById('stepsList').innerHTML = html;

if(dlType==='transfer'){
  document.getElementById('sec_applicant').style.display='none';
  document.getElementById('sec_transfer').style.display='block';
  populateCountries();
  populateCountryCodes('countryCodeSel2');
  var savedRadio = document.querySelector('input[name="country_in_transfer_list"][checked]');
  if(savedRadio){ savedRadio.checked=true; toggleTransferYesNo(savedRadio.value); }
} else {
  populateCountryCodes('countryCodeSel');
}

var FEE_MAP2={new:'1,890.00',amendment:'378.00',duplicate:'1,285.00',renewal:'1,285.00',transfer:'1,010.00'};
var STEPS2={
  new:['Application details','Declaration','Review application','Payment'],
  amendment:['Application details','Declaration','Review application','Payment'],
  duplicate:['Application details','Declaration','Review application','Payment'],
  renewal:['Application details','Declaration','Review application','Payment'],
  transfer:['Application details','Document submission','Declaration','Review application','Payment']
};
var parts=window.location.pathname.split('/');
var dlType=parts[parts.length-3];
var steps=STEPS2[dlType]||STEPS2['new'];
var activeIdx=dlType==='transfer'?2:1;
document.getElementById('declFee').textContent=FEE_MAP2[dlType]||'-';
var titleMap2={new:'New',amendment:'Amendment',duplicate:'Duplicate',renewal:'Renewal',transfer:'Transfer'};
document.getElementById('declTitle').textContent=titleMap2[dlType]||'New';
var html='';
steps.forEach(function(s,i){
  var done=i<activeIdx; var active=i===activeIdx;
  var cls=done?' done':active?' active':'';
  html+='

'+(done?'✓':(i+1))+'
'+s+'';
});
document.getElementById('declSteps').innerHTML=html;
document.getElementById('declForm').action='/spc/concierge/driving-license/'+dlType+'/declaration/submit';
var recId='';
document.getElementById('prevBtn').href=dlType==='transfer'
  ?'/spc/concierge/driving-license/transfer/step2/'+recId
  :'/spc/concierge/driving-license/'+dlType+'/step1';

var FEE_MAP3={new:'1,890.00',amendment:'378.00',duplicate:'1,285.00',renewal:'1,285.00',transfer:'1,010.00'};
var STEPS3={new:['Application details','Declaration','Review application','Payment'],
  amendment:['Application details','Declaration','Review application','Payment'],
  duplicate:['Application details','Declaration','Review application','Payment'],
  renewal:['Application details','Declaration','Review application','Payment'],
  transfer:['Application details','Document submission','Declaration','Review application','Payment']};
var parts=window.location.pathname.split('/');
var dlType=parts[parts.length-3];
var recordId=parts[parts.length-1];
var steps=STEPS3[dlType]||STEPS3['new'];
var activeIdx=steps.length-2;
document.getElementById('rvFee').textContent=FEE_MAP3[dlType]||'-';
var titleMap3={new:'New',amendment:'Amendment',duplicate:'Duplicate',renewal:'Renewal',transfer:'Transfer'};
document.getElementById('rvTitle').textContent=titleMap3[dlType]||'New';
var html='';
steps.forEach(function(s,i){
  var done=i<activeIdx; var active=i===activeIdx;
  var cls=done?' done':active?' active':'';
  html+='

'+(done?'✓':(i+1))+'
'+s+'';
});
document.getElementById('rvSteps').innerHTML=html;
document.getElementById('editBtn').href='/spc/concierge/driving-license/'+dlType+'/step1';
document.getElementById('prevBtn2').href='/spc/concierge/driving-license/'+dlType+'/declaration/'+recordId;
document.getElementById('nextBtn2').href='/spc/concierge/driving-license/'+dlType+'/payment/'+recordId;

var FEE_MAP4={new:'1,890.00',amendment:'378.00',duplicate:'1,285.00',renewal:'1,285.00',transfer:'1,010.00'};
var STEPS4={new:['Application details','Declaration','Review application','Payment'],
  amendment:['Application details','Declaration','Review application','Payment'],
  duplicate:['Application details','Declaration','Review application','Payment'],
  renewal:['Application details','Declaration','Review application','Payment'],
  transfer:['Application details','Document submission','Declaration','Review application','Payment']};
var parts=window.location.pathname.split('/');
var dlType=parts[parts.length-3]; var recordId=parts[parts.length-1];
var steps=STEPS4[dlType]||STEPS4['new'];
var fee=FEE_MAP4[dlType]||'-';
document.getElementById('payFee').textContent=fee;
document.getElementById('payAmt').textContent='AED '+fee;
document.getElementById('payTotal').textContent='AED '+fee;
var titleMap4={new:'New',amendment:'Amendment',duplicate:'Duplicate',renewal:'Renewal',transfer:'Transfer'};
document.getElementById('payTitle').textContent=titleMap4[dlType]||'New';
document.getElementById('payDesc').textContent='Driving License '+titleMap4[dlType]+' Fee';
var html='';
steps.forEach(function(s,i){
  var done=i<steps.length-1; var active=i===steps.length-1;
  var cls=done?' done':active?' active':'';
  html+='

'+(done?'✓':(i+1))+'
'+s+'';
});
document.getElementById('paySteps').innerHTML=html;
document.getElementById('payPrev').href='/spc/concierge/driving-license/'+dlType+'/review/'+recordId;
